import type { NextConfig } from "next";
import { securityHeaders } from "./src/lib/security-headers.ts";

const nextConfig: NextConfig = {
  // Security headers on every page and API response (HSTS, no framing, nosniff, referrer and permissions policy, CSP in report-only mode).
  // Static files get the same through public/_headers (generated by scripts/write-static-headers.mjs).
  async headers() {
    return [{ source: "/:path*", headers: securityHeaders() }];
  },
};

export default nextConfig;
